const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  // A1 portrait dimensions (scaled up for quality)
  const width = 794; // A1 width in pixels at 96dpi
  const height = 1123; // A1 height in pixels at 96dpi

  await page.setViewportSize({ width, height });

  const htmlPath = 'file://' + path.resolve('/app/output/book-history-poster.html');
  await page.goto(htmlPath, { waitUntil: 'networkidle' });

  // Wait for fonts and rendering
  await page.waitForTimeout(2000);

  // Capture the poster
  const screenshot = await page.screenshot({
    type: 'png',
    fullPage: true
  });

  require('fs').writeFileSync('/app/output/final_poster.png', screenshot);

  console.log('Poster saved to /app/output/final_poster.png');
  await browser.close();
})();
EOF
